function validate([nums]) {
  if (!Array.isArray(nums)) return 'nums must be an array.';
  if (nums.length < 2 || nums.length > 2000) return 'nums needs 2 to 2000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each value is an integer from 0 to 1000.';
  return null;
}

